INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 1, '0.	Heat oil in a cooking pot. Saute onion and garlic until onion softens');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 2, '1.	Add beef. Saute until the outer part turns light brown.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 3, '2.	Add soy sauce. Pour tomato sauce and water. Let boil.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 4, '3.	Add Knorr Beef Cube. Cover the pressure cooker. Cook for 30 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 5, '4.	Pan-fry carrot and potato until it browns. Set aside.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 6, '5.	Add chili pepper, liver spread and peanut butter. Stir.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 7, '6.	Add bell peppers, fried potato and carrot. Cover the pot. Continue cooking for 5 to 7 minutes.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000cf4e', 8, '7.	Season with salt and ground black pepper. Serve.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000ce89', 'Beef Dumpling Stew', 'Danie: British. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
