INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d034', 'Tomato Puree', 30, 'ml', 16);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 1, 'step 1');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 2, 'Put the cabbage in a heavy casserole dish, add the stock and cook over a low heat for about 50 mins, until tender.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 3, 'step 2');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 4, 'Cut the soaked mushrooms into strips and save the soaking water. Heat the lard and fry the sausages and bacon, then scoop out, leaving the fat in the pan. Fry the onion in the same pan for 5-8 mins until lightly browned.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 5, 'step 3');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000d034', 6, 'Add the mushrooms and their liquid along with all the cooked meat, onions and prunes, then cover and cook for 20 mins. Add the spices, red wine and tomato purée and bring to a simmer, then cover and cook for 1 hr. Season well and leave to cool. Will keep covered and chilled for up to two days. Bigos improves in flavour over a couple of days. Leave to cool first. Reheat until piping hot before serving.');
